/**
 * @file XSectionManager.cc
 * @brief Code for extracting cross-sections
 *
 */

#include "FastFrames/XSectionManager.h"
#include "FastFrames/Logger.h"
#include "FastFrames/Utils.h"
#include "FastFrames/StringOperations.h"

#include <fstream>
#include <stdexcept>

using std::string, std::map, std::vector, std::ifstream;


XSectionManager::XSectionManager(const std::vector<std::string> &xSectionFiles, const std::vector<int> &usedDSIDs) :
    m_usedDSIDs(usedDSIDs) {

    // we need PMG files first, so that we can compare x-section for the latest e-tag with the one from TopDataPreparation
    vector<string> xSectionFilesSorfted = xSectionFiles;
    std::sort(xSectionFilesSorfted.begin(), xSectionFilesSorfted.end(), [this](const string &a, const string &b) {
        return int(getFileType(a) != XSectionFileType::PMG) < int(getFileType(b) != XSectionFileType::PMG);
    });

    for (const string &xSectionFile : xSectionFilesSorfted) {
        readXSectionFile(xSectionFile);
    }
};

double XSectionManager::xSection(const int sampleDSID) const    {
    if (m_xSectionMap.find(sampleDSID) == m_xSectionMap.end()) {
        LOG(ERROR) << "Cannot find cross section for DSID: " << sampleDSID << ", please update your x-section file\n";
        throw std::runtime_error("");
    }
    return m_xSectionMap.at(sampleDSID).xSection;
};

void XSectionManager::readXSectionFile(const std::string &xSectionFile) {
    const XSectionFileType file_type = getFileType(xSectionFile);

    void(XSectionManager::*read_function)(const std::string &) = nullptr;
    if (file_type == XSectionFileType::TopDataPreparation) {
        LOG(WARNING) << "The Top Data Preparation x-section text file is deprecated and should not be used anymore. Please consider migrating to PMG files: /cvmfs/atlas.cern.ch/repo/sw/database/GroupData/dev/PMGTools/\n";
        read_function = &XSectionManager::processTopDataPreparationLine;
    }
    else if (file_type == XSectionFileType::PMG) {
        read_function = &XSectionManager::processPMGLine;
    }
    else {
        LOG(ERROR) << "Unsupported x-section file type\n";
        throw std::runtime_error("");
    }

    string line;
    ifstream input_file (xSectionFile);
    if (input_file.is_open())    {
        while ( getline (input_file,line) )        {
            (this->*read_function)(line);
        }
        input_file.close();
    }
    else    {
        LOG(ERROR) << "Unable to open x-section file \"" << xSectionFile << "\"\n";
        throw std::runtime_error("");
    }
};

void XSectionManager::processTopDataPreparationLine(const std::string &line)  {
    // For now just Top Data Preparation style x-section file is supported
    if (!validLine(line))   {
        return;
    }

    const vector<string> elements = StringOperations::splitByWhitespaces(line);
    const bool valid_line = validTopDataPreparationFileColumns(elements);

    if (!valid_line) {
        LOG(ERROR) << ("Invalid line in x-section text file: \"" + line + "\"\n");
        throw std::runtime_error("");
    }

    const int       dsid = std::stoi(elements.at(0));
    const double    xsec = std::stod(elements.at(1));
    const double    kfac = std::stod(elements.at(2));

    const double total_xsec = xsec * kfac;

    if (!m_usedDSIDs.empty() && std::find(m_usedDSIDs.begin(), m_usedDSIDs.end(), dsid) == m_usedDSIDs.end()) {
        return;
    }

    // Check if the sample is not defined multiple times in the x-section text file
    if (m_xSectionMap.find(dsid) != m_xSectionMap.end())    {
        if (!Utils::compareDoubles(m_xSectionMap.at(dsid).xSection, total_xsec, m_xsection_difference_tolerance))   {
            LOG(ERROR) << ("The following dsid was found multiple times in the x-section text files: \"" + elements.at(0) + "\"\n");
            throw std::runtime_error("");
        }
    }

    XSectionData xsection_data;
    xsection_data.xSection = total_xsec;
    xsection_data.eTag = 0;
    m_xSectionMap.insert({dsid, xsection_data});
};

XSectionFileType XSectionManager::getFileType(const std::string &xSectionFile) const {
    string line;
    ifstream input_file (xSectionFile);
    if (input_file.is_open())    {
        while ( getline (input_file,line) )        {
            if (!validLine(line))   {
                continue;
            }
            const std::vector<std::string> elements = StringOperations::splitByWhitespaces(line);
            if (validTopDataPreparationFileColumns(elements))   {
                return XSectionFileType::TopDataPreparation;
            }
            else if (validPMGFileColumns(elements)) {
                return XSectionFileType::PMG;
            }
            else if (StringOperations::stringStartsWith(line, "dataset_number/I:physics_short/C:crossSection_pb/D:genFiltEff/D:kFactor/D:relUncertUP/D:relUncertDOWN/D:generator_name/C:etag/C"))   {
                return XSectionFileType::PMG;
            }
            else {
                return XSectionFileType::Unknown;
            }
        }
        input_file.close();
        return XSectionFileType::Unknown;
    }
    else    {
        LOG(ERROR) << "Unable to open x-section file \"" << xSectionFile << "\"\n";
        throw std::runtime_error("");
    }
};

bool XSectionManager::validLine(const std::string &line) const  {
    string strippedString = line;
    StringOperations::stripString(&strippedString);

    if (strippedString.size() == 0)    {
        return false;
    }

    return strippedString.at(0) != '#';
};

void XSectionManager::processPMGLine(const std::string &line)    {
    // For now just Top Data Preparation style x-section file is supported
    if (!validLine(line))   {
        return;
    }

    // skip header
    if (StringOperations::stringStartsWith(line, "dataset_number/I"))    {
        return;
    }

    const vector<string> elements = StringOperations::splitByWhitespaces(line);

    const bool line_is_valid =  validPMGFileColumns(elements);

    if (!line_is_valid) {
        LOG(ERROR) << ("Invalid line in x-section text file: \"" + line + "\"\n");
        throw std::runtime_error("");
    }

    const int       dsid = std::stoi(elements.at(0));
    const double    xsec = std::stod(elements.at(2));
    const double    filt = std::stod(elements.at(3));
    const double    kfac = std::stod(elements.at(4));
    const int       etag = std::stoi(elements.at(8).substr(1));

    const double total_xsec = xsec * kfac * filt;

    if (!m_usedDSIDs.empty() && std::find(m_usedDSIDs.begin(), m_usedDSIDs.end(), dsid) == m_usedDSIDs.end()) {
        return;
    }

    // Check if the sample is not defined multiple times in the x-section text file
    if (m_xSectionMap.find(dsid) != m_xSectionMap.end())    {
        const int old_etag = m_xSectionMap.at(dsid).eTag;
        // already defined in TopDataPreparation file or with the same e-tag in PMG file
        if (old_etag <= 0 || old_etag == etag) {
            const double old_xsec = m_xSectionMap.at(dsid).xSection;

            if (!Utils::compareDoubles(old_xsec, total_xsec, m_xsection_difference_tolerance))   {
                LOG(ERROR) << ("The cross section for this DSID is defined multiple times with incompatible cross-sections with the same etag, or in both PMG and TopDataPreparation files. DSID: \"" + elements.at(0) + "\". Please fix it.\n");
                throw std::runtime_error("");
            }
        }
        else if (old_etag < etag) {
            XSectionData data;
            data.xSection = total_xsec;
            data.eTag = etag;
            m_xSectionMap.at(dsid) = data;
        }
    }
    else {
        XSectionData data;
        data.xSection = total_xsec;
        data.eTag = etag;
        m_xSectionMap.insert({dsid,data});
    }
};

bool XSectionManager::validTopDataPreparationFileColumns(const std::vector<std::string> &columns)   {
    const bool line_is_valid =  columns.size() < 3 ? false :
                                StringOperations::stringIsInt(columns.at(0)) &&    // DSID
                                StringOperations::stringIsDouble(columns.at(1)) &&  // x-section
                                StringOperations::stringIsDouble(columns.at(2));    // k-factor

    return line_is_valid;
};

bool XSectionManager::validPMGFileColumns(const std::vector<std::string> &columns) {
    const bool line_is_valid =  columns.size() < 9 ? false :
                                StringOperations::stringIsInt(columns.at(0)) &&            // DSID
                                StringOperations::stringIsDouble(columns.at(2)) &&          // x-section
                                StringOperations::stringIsDouble(columns.at(3)) &&          // filter efficiency
                                StringOperations::stringIsDouble(columns.at(4)) &&          // k-factor
                                StringOperations::stringStartsWith(columns.at(8), "e") &&  // e-tag
                                StringOperations::stringIsInt(columns.at(8).substr(1));    // e-tag
    return line_is_valid;
};

#!/bin/env python3

"""!Script for checking duplicate events in the input root files, based on runNumber and eventNumber.
"""

from ROOT import TFile
import os, sys
import argparse


this_dir = "/".join(os.path.dirname(os.path.abspath(__file__)).split("/")[0:-1])
sys.path.append(this_dir)

from ConfigReaderModules.BlockReaderCommon import set_paths
set_paths()

from ConfigReaderCpp import DuplicateEventChecker, DoubleVector, StringVector
from python_wrapper.python.logger import Logger
from produce_filelist import get_list_of_root_files_in_folder, get_file_metadata, Metadata

def get_metadata_to_list_of_root_files_dict(root_files_folder : str) -> dict[tuple, list[str]]:
    """!Get dictionary with metadata tuple as key and list of root files as value
    @param root_files_folder: folder with root files
    @return dict
    """
    result = {}
    root_files = get_list_of_root_files_in_folder(root_files_folder)
    for root_file in root_files:
        metadata = get_file_metadata(root_file)
        if metadata.get_metadata_tuple() in result:
            result[metadata.get_metadata_tuple()].append(root_file)
        else:
            result[metadata.get_metadata_tuple()] = [root_file]
    return result

def check_duplicate_events_in_folder(root_files_folder : str):
    """!Check duplicate events in the input root files
    @param root_files_folder: folder with root files
    """
    metadata_to_list_of_root_files_dict = get_metadata_to_list_of_root_files_dict(root_files_folder)
    for metadata_tuple, root_files in metadata_to_list_of_root_files_dict.items():
        root_files_vector = StringVector()
        for root_file in root_files:
            root_files_vector.append(root_file)
        duplicate_event_checker = DuplicateEventChecker(root_files_vector)
        duplicate_event_checker.checkDuplicateEntries()

        duplicate_run_numbers = duplicate_event_checker.duplicateRunNumbers()
        duplicate_event_numbers = duplicate_event_checker.duplicateEventNumbers()

        if len(duplicate_event_numbers) == 0:
            continue
        elif len(duplicate_event_numbers) < 10:
            Logger.log_message("WARNING", "Duplicate events found in unique sample: " + str(metadata_tuple) + " list of their event numbers and run numbers:")
            for i in range(len(duplicate_event_numbers)):
                Logger.log_message("WARNING", "\trunNumber: " + str(duplicate_run_numbers[i]) + "\t\teventNumber: " + str(duplicate_event_numbers[i]))
        else:
            Logger.log_message("WARNING", "Duplicate events found in unique sample: " + str(metadata_tuple) + " number of duplicate events: " + str(len(duplicate_event_numbers)))

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--root_files_folder",  help="Path to folder containing root files")
    args = parser.parse_args()
    check_duplicate_events_in_folder(args.root_files_folder)

#!/usr/bin/env python3

"""!Script for merging the output ROOT files
"""
import os
import sys

from ROOT import TFile, TH1D

this_dir = "/".join(os.path.dirname(os.path.abspath(__file__)).split("/")[0:-1])
sys.path.append(this_dir)

from ConfigReaderModules.BlockReaderCommon import set_paths
set_paths()

from python_wrapper.python.logger import Logger
from ConfigReader import ConfigReader, vector_to_list
from ConfigReaderModules.BlockReaderSample import BlockReaderSample
from CommandLineOptions import CommandLineOptions

def force_corrections_range(correction : TH1D) -> None:
    """!Force the range of the correction histogram to be between 0 and 1
    @param correction: histogram to be forced
    """
    for i_bin in range(0, correction.GetNbinsX() + 2):
        if correction.GetBinContent(i_bin) < 0:
            correction.SetBinContent(i_bin, 0)
        if correction.GetBinContent(i_bin) > 1:
            correction.SetBinContent(i_bin, 1)

def get_njobs_and_job_index_from_file_name(file_name : str, sample_name : str) -> tuple[int, int]:
    """! Decode the number of jobs and job index from the file name
    @param file_name: name of the file
    @param sample_name: name of the sample
    @return tuple[int, int] - number of jobs and job index
    """
    prefix = sample_name + "_Njobs_"
    name_skimmed = file_name[len(prefix):]
    try:
        njobs = int(name_skimmed.split("_")[0])
        job_index = int(name_skimmed.split("_")[2].replace(".root", ""))
        return (njobs, job_index)
    except Exception:
        Logger.log_message("ERROR", "Could not parse the file name: " + file_name)
        exit(1)

def get_sample_name_to_list_of_subjob_outputs(original_root_files : list[str], sample_names : list[str]) -> dict[str, list[str]]:
    """!Get dictionary with sample names as keys and list of subjob outputs as values
    @param original_root_files: list of all original root files
    @param sample_names: list of sample names
    @return dict[str, list[str]]
    """
    result = {}
    for sample_name in sample_names:
        # example name: ttbar_FS_Njobs_4_jobIndex_0.root
        prefix = sample_name + "_Njobs_"
        files_unmerged = [file for file in original_root_files if file.startswith(prefix)]

        # check consistency, i.e. if all files have the same number of jobs and if all job indices are present
        njobs = None
        job_indices = []
        for file in files_unmerged:
            njobs_file, job_index_file = get_njobs_and_job_index_from_file_name(file, sample_name)
            if njobs == None:
                njobs = njobs_file
            else:
                if njobs != njobs_file:
                    Logger.log_message("ERROR", "Inconsistent number of jobs for sample " + sample_name + ". Please clean up the folder and keep only files with the same Njobs parameter")
                    exit(1)
            job_indices.append(job_index_file)

        # check if all job indices are present
        for i_job in range(njobs):
            if i_job not in job_indices:
                Logger.log_message("ERROR", "Missing job index " + str(i_job) + " for sample " + sample_name)
                exit(1)

        result[sample_name] = files_unmerged
    return result

def merge_files(input_files : list[str], output_file : str, apply_cap : bool, truth_blocks : dict[str,list[tuple[str,str]]] = None, regions : list[str] = None) -> None:
    """!Merge input files into the output file
    @param input_files: list of input files
    @param output_file: output file
    @param truth_blocks: dictionary, key = truth block name, value = list of tuples, each containing two strings: reco-level name and truth-level name
    @param regions: list of regions
    """
    command = "hadd -f " + output_file + " " + " ".join(input_files)
    Logger.log_message("DEBUG", "Going to execute: " + command)
    os.system(command)

    if truth_blocks == None:
        return

    file = TFile.Open(output_file, "UPDATE")
    directories = [key.GetName() for key in file.GetListOfKeys() if key.GetClassName() == "TDirectoryFile"]
    for directory in directories:
        histograms_names = [key.GetName() for key in file.Get(directory).GetListOfKeys() if key.GetClassName() == "TH1D" or key.GetClassName() == "TH2D" or key.GetClassName() == "TH3D"]
        for region in regions:
            for truth_block_name in truth_blocks:
                for reco_truth_tuple in truth_blocks[truth_block_name]:
                    reco,truth = reco_truth_tuple
                    truth_histogram_name    = truth_block_name + "_" + truth
                    reco_histogram_name     = reco + "_" + region
                    migration_matrix_name   = truth_histogram_name + "_vs_" + reco + "_" + region
                    if (migration_matrix_name not in histograms_names) or (reco_histogram_name not in histograms_names):
                        Logger.log_message("DEBUG", "Skipping histogram: " + reco_histogram_name + " in folder " + directory)
                        continue
                    truth_histo = file.Get(truth_histogram_name)
                    reco_histo  = file.Get(directory + "/" + reco_histogram_name)
                    migration_matrix = file.Get(directory + "/" + migration_matrix_name) # truth on x-axis, reco on y-axis

                    acceptance = migration_matrix.ProjectionY() / reco_histo
                    efficiency = migration_matrix.ProjectionX() / truth_histo

                    if apply_cap:
                        force_corrections_range(acceptance)
                        force_corrections_range(efficiency)

                    acceptance.SetDirectory(0)
                    efficiency.SetDirectory(0)

                    file.cd(directory)
                    acceptance.Write("acceptance_{}_{}_{}".format(truth_block_name, reco, region), 1)
                    efficiency.Write("selection_eff_{}_{}".format(truth_histogram_name, region), 1)
    file.Close()

def get_unfolding_info(config_reader : ConfigReader, sample_name : str) -> dict[str, list[tuple[str,str]]]:
    """!Get dictionary with truth blocks as keys and list of tuples, each containing two strings: reco-level name and truth-level name
    @param config_reader: instance of ConfigReader
    @param sample_name: name of the sample
    @return dict[str, list[tuple[str,str]]]
    """
    samples = config_reader.block_general.get_samples_objects()
    result = {}
    for sample in samples:
        if sample_name != sample.name():
            continue
        truth_objects = BlockReaderSample.get_truth_cpp_objects(sample.getTruthSharedPtrs())
        for cpp_truth_object in truth_objects:
            truth_block_name = cpp_truth_object.name()
            result[truth_block_name] = []
            n_matched_variables = cpp_truth_object.nMatchedVariables()
            for i_match_variable in range(n_matched_variables):
                reco,truth = cpp_truth_object.matchedVariables(i_match_variable)
                result[truth_block_name].append((reco, truth))
        return result
    return None

if __name__ == "__main__":
    config_path = CommandLineOptions().get_config_path()

    Logger.log_message("INFO", "Going to read the config: " + config_path)
    config_reader = ConfigReader(config_path)

    output_path = config_reader.block_general.cpp_class.outputPathHistograms()
    sample_objects = config_reader.block_general.get_samples_objects()
    apply_cap = config_reader.block_general.cpp_class.capAcceptanceSelection()

    original_root_files = [file for file in os.listdir(output_path) if file.endswith(".root")]
    sample_names = [sample_object.name() for sample_object in sample_objects]
    sample_to_unmerged_files_list_dict = get_sample_name_to_list_of_subjob_outputs(original_root_files, sample_names)

    for sample_object in sample_objects:
        regions = vector_to_list(sample_object.regionsNames())
        sample_name = sample_object.name()
        merged_file_address = output_path + "/" + sample_name + ".root"

        unmerged_files = [output_path + "/" + filename for filename in sample_to_unmerged_files_list_dict[sample_name]]
        truth_blocks = get_unfolding_info(config_reader, sample_name)
        merge_files(unmerged_files, merged_file_address, apply_cap, truth_blocks, regions)

#!/bin/env python3

"""!Script for producing filelist.txt from a folder containing root files, it can be also imported as a module.
"""

from ROOT import TFile
import os, sys
import argparse

this_dir = "/".join(os.path.dirname(os.path.abspath(__file__)).split("/")[0:-1])
sys.path.append(this_dir)

from ConfigReaderModules.BlockReaderCommon import set_paths
set_paths()

from python_wrapper.python.logger import Logger

class Metadata:
    """!Python class for storing metadata (DSID, campaign and data_type) of a root file. It is used in produce_filelist.py
    """
    def __init__(self):
        """!Constructor of the Metadata class
        """
        ## DSID of the sample (int)
        self.dsid        = 0

        ## Campaign of the sample (string)
        self.campaign    = ""

        ## Data type of the sample (string)
        self.data_type = "mc"

    def get_metadata_tuple(self):
        """!Returns a tuple of (dsid, campaign, data_type)
        """
        return (self.dsid, self.campaign, self.data_type)

def get_list_of_root_files_in_folder(folder_path : str) -> list:
    """!Get list of all root files in the input folder, if it contains a folder, go recursively through it
    @param folder_path: path to the folder
    @return list of paths to root files
    """
    result = [os.path.abspath(os.path.join(folder_path, file)) for file in os.listdir(folder_path) if file.endswith(".root")]
    for directory in os.listdir(folder_path):
        if os.path.isdir(os.path.join(folder_path, directory)):
            result += get_list_of_root_files_in_folder(os.path.join(folder_path, directory))
    return result

def get_metadata_string(root_file : TFile, key : str) -> str:
    """!Get given metadata as string from the input ROOT file
    @param root_file: input ROOT file
    @param key: key of the metadata
    @return str
    """
    tnamed_object = root_file.Get(key)
    if tnamed_object == None:
        raise Exception("Could not find key {} in file {}".format(key, root_file.GetName()))
    return tnamed_object.GetTitle()

def get_file_metadata_old_format(file_path : str) -> Metadata:
    """!Get metadata object of the input ROOT file
    @param file_path: path to the ROOT file
    @return metadata object
    """
    metadata = Metadata()
    root_file = TFile.Open(file_path)
    metadata.dsid        = int(get_metadata_string(root_file, "dsid"))
    metadata.campaign    = get_metadata_string(root_file, "campaign")
    metadata.data_type = get_metadata_string(root_file, "dataType")
    root_file.Close()
    return metadata


def get_file_metadata(file_path : str) -> Metadata:
    """!Get metadata object of the input ROOT file
    @param file_path: path to the ROOT file
    @return metadata object
    """
    metadata = Metadata()
    root_file = TFile.Open(file_path)
    metadata_histo = root_file.Get("metadata")
    if metadata_histo == None:
        Logger.log_message("WARNING", "No metadata histogram in file {}".format(file_path))
        return get_file_metadata_old_format(file_path)
        exit()
    metadata.data_type   = metadata_histo.GetXaxis().GetBinLabel(1)
    metadata.campaign    = metadata_histo.GetXaxis().GetBinLabel(2)
    metadata.dsid        = int(metadata_histo.GetXaxis().GetBinLabel(3))
    root_file.Close()
    return metadata

def produce_filelist(root_files_folder : str, filelist_address : str, is_remote_eos_access : bool) -> None:
    """!Produce filelist from all the root files in the input root_files_folder. The filelist will be saved to filelist_address
    @param root_files_folder: path to the folder containing root files
    @param filelist_address: path to the output filelist
    """
    sample_map = {}

    root_files = get_list_of_root_files_in_folder(root_files_folder)
    for root_file in root_files:
        metadata = get_file_metadata(root_file)
        metadata_tuple = metadata.get_metadata_tuple()
        if metadata_tuple not in sample_map:
            sample_map[metadata_tuple] = []
        sample_map[metadata_tuple].append(root_file)

    MAX_METADATA_ITEM_LENGTHS = [8 for i in range(len(metadata_tuple))]
    with open(filelist_address, "w") as filelist:
        for metadata_tuple, root_files in sample_map.items():
            for root_file in root_files:
                for metadata_element in metadata_tuple:
                    n_spaces = MAX_METADATA_ITEM_LENGTHS[metadata_tuple.index(metadata_element)] - len(str(metadata_element))
                    filelist.write(str(metadata_element) + n_spaces*" ")
                if(is_remote_eos_access):
                    root_file = "root://eosatlas.cern.ch/"+root_file
                filelist.write("{}\n".format(root_file))

def produce_filelist_grid(grid_paths_dict : dict, filelist_address : str) -> None:
    """!Produce filelist from all the root files in the input root_files_folder. The filelist will be saved to filelist_address
    @param root_files_folder: path to the folder containing root files
    @param filelist_address: path to the output filelist
    """
    # First clean the file if it already exists
    with open(filelist_address, "w") as filelist:
        filelist.write("")
    counter = 1 # To keep track of the progress
    for grid_sample, grid_paths in grid_paths_dict.items():
        Logger.log_message("INFO", "Creating file list for sample"+grid_sample+"... "+str(counter)+"/"+str(len(grid_paths_dict)))

        sample_map = {}

        root_files = grid_paths
        for root_file in root_files:
            metadata = get_file_metadata(root_file)
            metadata_tuple = metadata.get_metadata_tuple()
            if metadata_tuple not in sample_map:
                sample_map[metadata_tuple] = []
            sample_map[metadata_tuple].append(root_file)

        MAX_METADATA_ITEM_LENGTHS = [8 for i in range(len(metadata_tuple))]
        with open(filelist_address, "a+") as filelist:
            for metadata_tuple, root_files in sample_map.items():
                for root_file in root_files:
                    for metadata_element in metadata_tuple:
                        n_spaces = MAX_METADATA_ITEM_LENGTHS[metadata_tuple.index(metadata_element)] - len(str(metadata_element))
                        filelist.write(str(metadata_element) + n_spaces*" ")
                    filelist.write("{}\n".format(root_file))
        counter += 1

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--root_files_folder",  help="Path to folder containing root files")
    parser.add_argument("--output_path",        help="Address of the output filelist", nargs = '?', default="")
    args = parser.parse_args()
    root_files_folder = args.root_files_folder
    output_path = args.output_path if args.output_path != "" else root_files_folder + "/filelist.txt"

    produce_filelist(root_files_folder, output_path)

"""
@file Source file of AutomaticRangeGenerator class.
"""

from copy import deepcopy
from BlockReaderCommon import set_paths
set_paths()

from python_wrapper.python.logger import Logger
from BlockOptionsGetter import BlockOptionsGetter

class AutomaticRangeGenerator:
    """
    AutomaticRangeGenerator class is used to generate a sequence of block based on the numbering sequence defined in the input block,
    for example unrolling one jet#N_pt into blocks for jet1_pt, jet2_pt, etc.
    """
    def __init__(self, list_of_replacement_sequences : list[dict]):
        """!Constructor of AutomaticRangeGenerator
        @param list_of_replacement_sequences: list[dict] - list of numbering sequences blocks from config
        """
        self.replace_sequences = deepcopy(list_of_replacement_sequences)

    def generate_range(self, input_block : dict, keys_to_replace : list[str]) -> list[dict]:
        """!Generate a range of blocks based on the numbering sequence defined in the input block
        @param input_block: dict - block contaning the replacement string, so for example jet#N_pt
        @param keys_to_replace: list[str] - list of keys to replace in the input block, so for example ["defintion", "name", "title"],
            it also supports nested blocks, where [["variation", "up"], ["variation", "down"], ["name"] will replace the corresponding values in subblocks
        @return list[dict]
        """
        updated_keys_to_replace = []
        for key in keys_to_replace:
            if type(key) == str:
                updated_keys_to_replace.append([key])
            else:
                updated_keys_to_replace.append(key)
        return self._generate_range(input_block, updated_keys_to_replace, self.replace_sequences)

    def _get_block_to_update(input_block : dict, keys_to_replace : list) -> dict:
        block_to_update = input_block
        for i_key in range(len(keys_to_replace)-1):
            key = keys_to_replace[i_key]
            if key in block_to_update:
                block_to_update = block_to_update[key]
            else:
                return None
        return block_to_update

    def _get_replacement_string_and_values(self, replacement_sequence : dict) -> tuple[str,list[str]]:
            this_replacement = BlockOptionsGetter(replacement_sequence)
            replacement_string = this_replacement.get("replacement_string", None, [str])
            squence_min = this_replacement.get("min", None, [int])
            squence_max = this_replacement.get("max", None, [int])
            sequence_values = this_replacement.get("values", None, [list], [str])
            unused_keys = this_replacement.get_unused_options()
            if len(unused_keys) > 0:
                raise ValueError("Unused keys in replacement sequence: {}".format(replacement_sequence))

            if replacement_string is None:
                raise ValueError("No replacement string specified in replacement sequence: {}".format(replacement_sequence))

            range_based = squence_min is not None and squence_max is not None
            value_based = sequence_values is not None

            if not (range_based ^ value_based):
                raise ValueError("Exactly one of min/max or values should be specified in replacement sequence: {}".format(replacement_sequence))
            elif range_based:
                return replacement_string,[str(index) for index in range(squence_min, squence_max + 1)]
            else:
                return replacement_string,sequence_values

    def _generate_range(self, input_block : dict, keys_to_replace : list[list[str]], replacement_sequences : list[dict]) -> list[dict]:
        if len(replacement_sequences) == 0:
            return [input_block]
        else:
            replacement_string, replaced_values = self._get_replacement_string_and_values(replacement_sequences[0])
            result = []
            for index in replaced_values:
                updated_block = deepcopy(input_block)
                for key_to_replace in keys_to_replace:
                    sub_block = AutomaticRangeGenerator._get_block_to_update(updated_block, key_to_replace)
                    if sub_block is None:
                        continue
                    key = key_to_replace[-1]
                    if key not in sub_block:
                        continue
                    sub_block[key] = sub_block[key].replace(replacement_string, index)
                result += self._generate_range(updated_block, keys_to_replace, replacement_sequences[1:])
            return result

    def unroll_sequence(list_of_block_dicts : list[dict], keys_to_update : list[str] = None) -> list[dict]:
        """!If numbering_sequence block is defined in a block, unroll the block into multiple blocks with different values of "keys_to_update" based on the numbering sequence
        @param list_of_block_dicts: list[dict]
        @param keys_to_update: list[str]
        @return list[dict]
        """
        result = []
        calculate_keys_to_update = keys_to_update is None
        list_of_block_dicts_copy = deepcopy(list_of_block_dicts)
        for block_dict in list_of_block_dicts_copy:
            if "numbering_sequence" not in block_dict:
                result.append(block_dict)
                continue
            replacement_sequences = block_dict["numbering_sequence"]
            if calculate_keys_to_update:
                keys_to_update = AutomaticRangeGenerator._get_list_of_keys_to_update(block_dict)
            if not isinstance(replacement_sequences, list):
                Logger.log_message("ERROR", "Replacement sequences should be a list. Maybe you forgot '-' ?")
                exit(1)
            del block_dict["numbering_sequence"]
            generator = AutomaticRangeGenerator(replacement_sequences)
            result += generator.generate_range(block_dict, keys_to_update)
        return result


    def _get_list_of_keys_to_update(block_dict : dict) -> list[list[str]]:
        if "numbering_sequence" not in block_dict:
            return []
        replacement_strings = []
        for replacement_sequence in block_dict["numbering_sequence"]:
            if not "replacement_string" in replacement_sequence:
                Logger.log_message("ERROR", "No replacement string specified in one of the numbering sequences")
                exit(1)
            replacement_strings.append(replacement_sequence["replacement_string"])

        def get_keys_to_update(block_dict : dict, replacement_strings : list[str], address : list[str]) -> list:
            keys_to_update = []
            for key, value in block_dict.items():
                if isinstance(value, str):
                    for replacement_string in replacement_strings:
                        if replacement_string in value:
                            keys_to_update.append(address + [key])
                if isinstance(value, dict):
                    keys_to_update = keys_to_update + get_keys_to_update(value, replacement_strings, address + [key])

            return keys_to_update

        return get_keys_to_update(block_dict, replacement_strings, [])

"""
@file Source file with BlockOptionsGetter and VariationsOptionsGetter classes.
"""
from copy import deepcopy
from python_wrapper.python.logger import Logger

class BlockOptionsGetter:
    """!Class used to extract options defined in a block of the config file.
    It works like a dictionary, but allows to check if all options from config were used in the code.
    """

    def __init__(self, config_dict : dict):
        """!Constructor of the BlockOptionsGetter class
        @param self
        @param config_dict: dictionary with options from the config file
        """
        self._config = config_dict
        self._option_used = deepcopy(config_dict)
        for option in self._option_used:
            self._option_used[option] = False


    def get(self, option : str, default_value = None, allowed_types : list = None, allowed_elements : list = None):
        """!Get option from the config file. If the option is not present, return default_value. If the option is present, check if it matches allowed_types.
        @param option: option to be read
        @param default_value: value to be returned if the option is not present
        @param allowed_types: list of allowed types for the option
        @param allowed_elements: if the value is iterable, you can specify allowed types for its elements
        """
        if option not in self._config:
            return default_value
        self._option_used[option] = True
        return_value = self._config[option]
        if allowed_types is not None and type(return_value) not in allowed_types:
            Logger.log_message("ERROR", "Option {} has invalid type: {} (allowed types: {})".format(option, type(return_value), allowed_types))
            exit(1)
        if allowed_elements is not None and hasattr(return_value, "__iter__"):
            for element in return_value:
                if type(element) not in allowed_elements:
                    Logger.log_message("ERROR", "Option {} has invalid type of element: {} (allowed types: {}). The problematic value: {}".format(option, type(element), allowed_elements, return_value))
                    exit(1)
        return self._config[option]

    def get_unused_options(self):
        """!Get list of options that were not read
        """
        result = []
        for option in self._option_used:
            if not self._option_used[option]:
                result.append(option)
        return result

    def __contains__(self, option : str):
        """
        Defines in operator
        """
        return option in self._config

    def __getitem__(self, option : str):
        """
        Defines [] operator
        """
        return self._config[option]

    def __str__(self):
        """
        Conversion to string
        """
        return str(self._config)



class VariationsOptionsGetter:
    """!Class used to extract options defined in variation block of the systematics. Since the up and down variations are read separately, but their properties are defined in the same block, one cannot use BlockOptionsGetter to read them and check for unused options.
    """

    def __init__(self, config_dict : dict):
        """!Constructor of the VariationsOptionsGetter class
        @param config_dict: dictionary with options from the config file
        """
        self._config = config_dict
        self._option_used = {}
        for option in self._config:
            option_wo_variation_suffix = None
            if option.endswith("_up"):
                option_wo_variation_suffix = option[:-3]
            elif option.endswith("_down"):
                option_wo_variation_suffix = option[:-5]
            elif option == "up" or option == "down":
                option_wo_variation_suffix = ""
            else:
                Logger.log_message("Warning", "Unknown variation option: {}".format(option))
                continue
            self._option_used[option_wo_variation_suffix] = False

    def get(self, option : str, variation : str, default_value = None, allowed_types : list = None):
        """!Get option for the given variation from the config file. If the option is not present, return default_value. If the option is present, check if it matches allowed_types.
        @param option: option to be read
        @param variation: variation to be read (up or down)
        @param default_value: value to be returned if the option is not present
        @param allowed_types: list of allowed types for the option
        """
        key = option + "_"*(len(option) != 0) + variation
        if key not in self._config:
            return default_value
        self._option_used[option] = True
        return_value = self._config.get(key, default_value)
        if allowed_types is not None and type(return_value) not in allowed_types:
            Logger.log_message("ERROR", "Option {} has invalid type: {} (allowed types: {})".format(option, type(return_value), allowed_types))
            exit(1)
        return return_value

    def get_unused_options(self):
        """!Get list of options that were not read"""
        result = []
        for option in self._option_used:
            if not self._option_used[option]:
                result.append(option)
        return result

    def use_option(self, option : str):
        """!Mark option as used"""
        self._option_used[option] = True

