/**
 * @brief Main class that does all the hard work
 *
 */
class MainFrame {
public:

  /**
   * @brief Construct a new Main Frame object
   *
   */
  explicit MainFrame() : m_config(std::make_shared<ConfigSetting>()) {};

  /**
   * @brief Destroy the Main Frame object
