/**
 * @file SimpleONNXInference.h
 * @brief SimpleONNXInference
 *
 */

#pragma once

#ifdef ONNXRUNTIME_AVAILABLE
  #include "FastFrames/ONNXWrapper.h"
#endif

#include "FastFrames/Logger.h"

#include <string>
#include <vector>
#include <map>
#include <memory>
#include <stdexcept>

/**
 * @brief Class containing information for inference of a given simple ONNX model
 *
 */
class SimpleONNXInference {
public:

  /**
   * @brief Construct a new SimpleONNXInference object
   *
   * @param name Name of the ONNX model
   */
  explicit SimpleONNXInference(const std::string& name) noexcept;

  /**
   * @brief Deleted default constructor
   *
   */
  SimpleONNXInference()  = delete;

  /**
   * @brief Destroy the SimpleONNXInference object
   *
   */
  ~SimpleONNXInference() = default;

  /**
   * @brief Get the name of the SimpleONNXInference object
   *
   * @return const std::string&
   */
  inline const std::string& name() const {return m_name;}

  /**
   * @brief Sets the paths to the ONNX model files for k-fold inference
   *
   * @param paths List of paths to the ONNX model files
   */
  inline void setModelPaths(const std::vector<std::string>& paths) {
      m_modelPaths = paths;
  }

  /**
   * @brief Returns the list of paths to the ONNX model files
   *
   * @return List of paths to the ONNX model files
   */
  inline const std::vector<std::string>& modelPaths() const {
      return m_modelPaths;
  }

  /**
   * @brief Records the names fo the input columns corresponding to an input layer
   *
   * @param layer_name Name of the input layer
   * @param branch_names Names of the input columns
   */
  void addInput(const std::string& layer_name, const std::vector<std::string>& branch_names) {
      m_inputs.insert({layer_name, branch_names});
  }

  /**
   * @brief Records the names fo the output columns corresponding to an output layer
   *
   * @param layer_name Name of the output layer
   * @param branch_names Names of the output columns
   */
  void addOutput(const std::string& layer_name, const std::vector<std::string>& branch_names) {
      m_outputs.insert({layer_name, branch_names});
  }

  /**
   * @brief Sets the fold-formula for k-fold inference
   *
   * @note Not yet implemented
   */
  inline void setFoldFormula(const std::string& foldFormula) {
      if (foldFormula != "") {
          throw std::runtime_error("Custom fold_formula is not yet supported. It will be implemented later, if necessary.");
      }
      // m_foldFormula = foldFormula;
  }

  /**
   * @brief Initialize the underlying ONNXWrapper object with the given model paths
   *
   */
  inline void initializeModels() {
    #ifdef ONNXRUNTIME_AVAILABLE
      m_onnx =  std::make_unique<ONNXWrapper>(m_name, m_modelPaths);
    #else
      LOG(WARNING) << "You are trying to use ONNX wrapper, but the onnxruntime is not available. Please rerun cmake and recompile with onnxruntime.\n";
      return;
    #endif
  }

  /**
   * @brief Runs k-fold inference
   *
   * @param outputLayer Name of the output layer
   * @param eventNumber Event number of the corresponding event, used for k-fold inference
   * @param inputs Map of input layer names and their corresponding input values
   * @return Output values from the specified the outputLayer
   */
  std::vector<float> runInference(const std::string& outputLayer, const unsigned long long& eventNumber, const std::map<std::string, std::vector<float>>& inputs)   const;

  inline std::vector<std::string> getInputColumnNames() {
      std::vector<std::string> columnNames{"eventNumber"};
      for (const auto &[input_name, branches]: m_inputs) {
          for (const std::string &branch: branches) {
              columnNames.push_back(branch);
          }
      }
      return columnNames;
  }

  /**
   * @brief Returns the map of input layer names and their corresponding input columns
   *
   * @return Map of input layer names and their corresponding input columns
   */
  inline const std::map<std::string, std::vector<std::string>>& getInputMap() {
      return m_inputs;
  }

  /**
   * @brief Returns the map of output layer names and their corresponding output columns
   *
   * @return Map of output layer names and their corresponding output columns
   */
  inline const std::map<std::string, std::vector<std::string>>& getOutputMap() {
      return m_outputs;
  }


  /**
   * @brief Helper class to dispatch one uint64_t and multiple float arguments to a function
   *
   * @note Use the variadicDispatch<N>(f) function to create an object of this class
   */
  template <typename I, typename F>
  class VariadicDispatcher;

  template <std::size_t... N, typename F>
  class VariadicDispatcher<std::index_sequence<N...>, F> {
    template <std::size_t>
    using RepeatedT = float;
    std::decay_t<F> fFunc;

  public:
    explicit VariadicDispatcher(F &&f) : fFunc(f) {}
    auto operator()(unsigned long long eventNumber, RepeatedT<N>... args) { return fFunc(eventNumber, {args...}); }
  };

  /**
   * @brief Helper function to dispatch one uint64_t and multiple float arguments to a function
   *
   * @tparam N Number of float arguments
   * @tparam F Function type
   * @param f Function to dispatch the arguments to
   * @return VariadicDispatcher object
   */
  template <std::size_t N, typename F>
  static auto variadicDispatch(F &&f)
  {
    return VariadicDispatcher<std::make_index_sequence<N>, F>(f);
  }

private:

  std::string m_name;
  std::vector<std::string> m_modelPaths;
  std::map<std::string, std::vector<std::string>> m_inputs;
  std::map<std::string, std::vector<std::string>> m_outputs;
  std::string m_foldFormula;
  #ifdef ONNXRUNTIME_AVAILABLE
    std::unique_ptr<ONNXWrapper> m_onnx;
  #endif
};

/**
 * @file StringOperations.h
 * @brief Helper functions for string operations
 *
 */

#pragma once

#include <string>
#include <vector>
#include <stdexcept>

/**
 * @brief A namespace containing various string manipulation functions
 */
namespace StringOperations  {

    /**
     * @brief Replaces all occurances of substring with another string
     *
     * @param original input string
     * @param from string to be replaced
     * @param to replace with
     * @return std::string
     */
    std::string replaceString(const std::string& original,
                              const std::string& from,
                              const std::string& to);

    /**
     * @brief calls replaceString on each element of a string vector
     *
     * @param input input string vector
     * @param from string to be replaced in each element
     * @param to replace with
     * @return std::vector<std::string>
     */
    std::vector<std::string> replaceVector(const std::vector<std::string>& input,
                                           const std::string& from,
                                           const std::string& to);

    /**
     * @brief String contains a substring
     *
     * @param main_string
     * @param substring
     * @return true
     * @return false
     */
    inline bool contains(const std::string &main_string, const std::string &substring)  {
        return (main_string.find(substring)) != std::string::npos;
    };

    /**
     * @brief String starts with a substring
     *
     * @param main_string
     * @param prefix
     * @return true
     * @return false
     */
    bool stringStartsWith(const std::string &main_string, const std::string &prefix);

    /**
     * @brief String ends with a substring
     *
     * @param main_string
     * @param suffix
     * @return true
     * @return false
     */
    bool stringEndsWith(const std::string &main_string, const std::string &suffix);

    /**
     * @brief String is an iteger
     *
     * @param input_string
     * @return true
     * @return false
     */
    bool stringIsInt(const std::string &input_string);

    /**
     * @brief String is a double
     *
     * @param input_string
     * @return true
     * @return false
     */
    bool stringIsDouble(const std::string &input_string);

    /**
     * @brief String is a float
     *
     * @param input_string
     * @return true
     * @return false
     */
    bool stringIsFloat(const std::string &input_string);

    /**
     * @brief Split string into substrings and remove whitespace
     *
     * @param input_string
     * @param separator
     * @return std::vector<std::string>
     */
    std::vector<std::string> splitAndStripString(const std::string &input_string, const std::string &separator);

    /**
     * @brief Split string into substring but keep whitespaces
     *
     * @param input_string
     * @param separator
     * @return std::vector<std::string>
     */
    std::vector<std::string> splitString(std::string input_string, const std::string &separator);

    /**
     * @brief Split string by whitesaces
     *
     * @param line
     * @return std::vector<std::string>
     */
    std::vector<std::string> splitByWhitespaces(std::string line);

    /**
     * @brief Remove characters from a string
     *
     * @param input_string
     * @param chars_to_remove
     */
    void stripString(std::string *input_string, const std::string &chars_to_remove = " \n\t\r");

    /**
     * @brief Switch all characters to upper case
     *
     * @param input_string
     */
    void         toUpper(std::string *input_string);

    /**
     * @brief Make a copy of a string with upper cases
     *
     * @param input_string
     * @return std::string
     */
    std::string  toUpperCopy(const std::string &input_string);

    /**
     * @brief Compares two string to upper case and compare them
     *
     * @param x
     * @param y
     * @return true
     * @return false
     */
    bool compare_case_insensitive(const std::string &x, const std::string &y);

    /**
     * @brief Convert string to a given format
     *
     * @tparam ResultType
     * @param input_string
     * @return ResultType
     */
    template <class ResultType>
    ResultType convertStringTo([[__maybe_unused__]]const std::string &input_string) {
        throw std::runtime_error ("Requested type not implemented!");
    };

    /**
     * @brief Convert string to an int
     *
     * @tparam
     * @param input_string
     * @return int
     */
    template <> inline
    int convertStringTo(const std::string &input_string)    {
        return std::stoi(input_string);
    };

    /**
     * @brief Convert string to an unsigned int
     *
     * @tparam
     * @param input_string
     * @return unsigned int
     */
    template <> inline
    unsigned int convertStringTo(const std::string &input_string)    {
        return std::stoul(input_string);
    };

    /**
     * @brief Convert string into unsigned long long int
     *
     * @tparam
     * @param input_string
     * @return unsigned long long int
     */
    template <> inline
    unsigned long long int convertStringTo(const std::string &input_string)    {
        return std::stoull(input_string);
    };

    /**
     * @brief Convert string to float
     *
     * @tparam
     * @param input_string
     * @return float
     */
    template <> inline
    float convertStringTo(const std::string &input_string)    {
        return std::stod(input_string);
    };

    /**
     * @brief Convert string to double
     *
     * @tparam
     * @param input_string
     * @return double
     */
    template <> inline
    double convertStringTo(const std::string &input_string)    {
        return std::stod(input_string);
    };

    /**
     * @brief Convert string to string - needed for other template functions
     *
     * @tparam
     * @param input_string
     * @return std::string
     */
    template <> inline
    std::string convertStringTo(const std::string &input_string)    {
        return input_string;
    };

    /**
     * @brief Convert \"true\" and \"false\" to boolean (case insensitive)
     *
     * @tparam
     * @param input_string
     * @return true
     * @return false
     */
    template <> inline
    bool convertStringTo(const std::string &input_string)    {
        const std::string inputUpper = StringOperations::toUpperCopy(input_string);
        if      (inputUpper == "TRUE")  return true;
        else if (inputUpper == "FALSE") return false;
        else {
            throw std::runtime_error("String \"" + input_string + "\" can't be converted to bool value!");
        }
    };

    /**
     * @brief Convert to a vector of integers needed for brackets treatment
     *
     * @tparam
     * @param input_string
     * @return std::vector<int>
     */
    template <> inline
    std::vector<int> convertStringTo(const std::string &input_string)    {
        std::string stripped_string = input_string;
        stripString(&stripped_string, "([{}})");
        std::vector<std::string> elements = splitAndStripString(stripped_string, ",");

        std::vector<int> result;
        for (const std::string &element : elements) {
            result.push_back(convertStringTo<int>(element));
        }
        return result;
    };

    /**
     * @brief Convert string to unsigned long long int needed for brackets treatment
     *
     * @tparam
     * @param input_string
     * @return std::vector<unsigned long long int>
     */
    template <> inline
    std::vector<unsigned long long int> convertStringTo(const std::string &input_string)    {
        std::string stripped_string = input_string;
        stripString(&stripped_string, "([{}})");
        std::vector<std::string> elements = splitAndStripString(stripped_string, ",");

        std::vector<unsigned long long int> result;
        for (const std::string &element : elements) {
            result.push_back(convertStringTo<unsigned long long int>(element));
        }
        return result;
    };


    /**
     * @brief Convert string to double needed for brackets treatment
     *
     * @tparam
     * @param input_string
     * @return std::vector<double>
     */
    template <> inline
    std::vector<double> convertStringTo(const std::string &input_string)    {
        std::string stripped_string = input_string;
        stripString(&stripped_string, "([{}})");
        std::vector<std::string> elements = splitAndStripString(stripped_string, ",");

        std::vector<double> result;
        for (const std::string &element : elements) {
            result.push_back(convertStringTo<double>(element));
        }
        return result;
    };

    /**
     * @brief equivalent to python's join function
     *
     * @param std::string
     * @param std::vector<std::string>
     * @return std::string
     */
    std::string joinStrings(const std::string &separator, const std::vector<std::string> &strings);


    /**
     * @brief Get valid C++ variable names from a string
     *
     * @param std::string - input
     * @return std::vector<std::pair<std::string,int>> - vector of all valid C++ variable names in the input string and start position
     */
    std::vector<std::pair<std::string,  int>> getValidCxxVariableNames(const std::string &input);
}

